from collections import defaultdict

def count_optimal_paths(N, edges):
    graph = defaultdict(list)

    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    total_paths = 0

    for node in range(1, N + 1):
        neighbors = graph[node]
        for neighbor in neighbors:
            for n_neighbor in graph[neighbor]:
                if n_neighbor != node and n_neighbor not in graph[node]:
                    total_paths += 1

    return total_paths // 3

